<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1"/>
<title>The Great Wave off Kanagawa - low poly 3D wallpaper</title>
<style>
  html,body{margin:0;height:100%;overflow:hidden;background:#e9dfc4}
  #app{position:fixed;inset:0}
  #label{position:fixed;left:14px;bottom:10px;font:12px/1.4 Georgia,serif;color:#2b3a55;opacity:.75;pointer-events:none}
</style>
</head>
<body>
<div id="app"></div>
<div id="label">Kanagawa Oki Nami Ura &middot; low poly wallpaper</div>
<script type="module">
import * as THREE from "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js";

/* ---- Palette taken from the print ---- */
const C = {
  paper:   0xe9dfc4,
  ink:     0x1d2a44,
  indigo1: 0x16324f, // deep wave body
  indigo2: 0x2a5d8f, // mid blue
  indigo3: 0x7fb2d9, // pale blue highlights
  foam:    0xf4f1e6,
  fuji:    0x4a5f8c,
  fujiCap: 0xf2efe4,
  hull:    0xd8b98a,
  hullDark:0x8a6f4d,
  rope:    0x6b5a42,
};

const renderer = new THREE.WebGLRenderer({antialias:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
renderer.setSize(innerWidth,innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
document.getElementById("app").appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(C.paper);
scene.fog = new THREE.Fog(C.paper, 30, 70);

const camera = new THREE.PerspectiveCamera(46, innerWidth/innerHeight, .1, 200);
camera.position.set(0, 5.5, 20);
camera.lookAt(0, 2.6, 0);

scene.add(new THREE.HemisphereLight(0xfff6e0, 0x8a94a8, 1.2));
const sun = new THREE.DirectionalLight(0xfff2d8, .5);
sun.position.set(-6, 10, 8);
scene.add(sun);

const flat = (color, opts={}) => new THREE.MeshLambertMaterial({color, flatShading:true, ...opts});

/* ============================================================
   Wave builder: a low-poly sheet whose height follows a ridge
   profile along its length, so crests read as sharp ridges.
   Returns the mesh; a foam strip is added along the crest.
   ============================================================ */
function makeWave({width=22, depth=14, segW=26, segD=16, color, phase=0,
                   ridge=1.6, rough=0.35, x=0, y=0, z=0, rotY=0, rotZ=0, rotX=0,
                   crestColor=null, crestWidth=0.18}={}) {
  const g = new THREE.PlaneGeometry(width, depth, segW, segD);
  g.rotateX(-Math.PI/2);
  const pos = g.attributes.position;
  let crestX = 0, crestH = 0;
  for (let i=0;i<pos.count;i++){
    const px = pos.getX(i), pz = pos.getZ(i);
    const t = (px/width + .5); // 0..1 along length
    let h = Math.sin(t*Math.PI + phase) * ridge;
    h += Math.sin(t*Math.PI*3.1 + phase*2.2) * rough * .5;
    h += (pz/depth) * ridge * .15;
    pos.setY(i, h);
    if (h > crestH){ crestH = h; crestX = px; }
  }
  g.computeVertexNormals();
  const m = new THREE.Mesh(g, flat(color));
  m.position.set(x,y,z);
  m.rotation.set(rotX, rotY, rotZ);
  m.userData = {baseY:y, baseRZ:rotZ, baseRX:rotX};
  scene.add(m);

  if (crestColor !== null){
    // foam: a row of small low-poly "claws" (cones) along the crest line
    const n = 9;
    for (let i=0;i<n;i++){
      const fx = -width/2 + (i/(n-1))*width;
      const ft = (fx/width + .5);
      const fh = Math.sin(ft*Math.PI + phase)*ridge + Math.sin(ft*Math.PI*3.1+phase*2.2)*rough*.5;
      const claw = new THREE.Mesh(new THREE.ConeGeometry(width/n*.42, .5, 5, 1), flat(crestColor));
      claw.position.set(fx, fh + .2, -depth*.12);
      claw.rotation.z = (Math.random()-.5)*.5;
      m.add(claw); // child so it moves with the wave
    }
  }
  return m;
}

